-- +goose Up
-- Catalog service: products, SKUs, prices, media.
-- SQLite version: 3.38+ recommended for JSON support.
-- UUIDs are generated by the application.
-- Timestamps use SQLite's UTC  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) format.
CREATE TABLE
    category (
        id TEXT PRIMARY KEY NOT NULL,
        parent_id TEXT REFERENCES category (id),
        name TEXT NOT NULL,
        slug TEXT NOT NULL UNIQUE,
        created_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
    );

CREATE INDEX idx_category_parent ON category (parent_id);

-- Seed categories
INSERT INTO category (id, parent_id, name, slug) VALUES
    ('cat-electronics', NULL, 'Electronics', 'electronics'),
    ('cat-mobiles', 'cat-electronics', 'Mobile Phones', 'mobile-phones'),
    ('cat-accessories', 'cat-electronics', 'Accessories', 'accessories'),
    ('cat-fashion', NULL, 'Fashion', 'fashion'),
    ('cat-mens-clothing', 'cat-fashion', 'Mens Clothing', 'mens-clothing');


CREATE TABLE
    product (
        id TEXT PRIMARY KEY NOT NULL,
        name TEXT NOT NULL,
        slug TEXT NOT NULL UNIQUE,
        description TEXT,
        category_id TEXT REFERENCES category (id),
        brand TEXT,
        status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'ARCHIVED')),
        created_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
        updated_at TEXT NOT NULL DEFAULT  (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
    );

CREATE INDEX idx_product_category ON product (category_id);

CREATE INDEX idx_product_status ON product (status);

